// cpp: css_value_keywords.cc:2398-2562
// The C++ switch falls through from len-1 down to 0. A descending loop performs
// those same additions; the four position-specific offsets are preserved.
fn value_hash_function(str: &[u8]) -> u32 {
    let mut hval = 0u32;
    for index in (0..str.len()).rev() {
        let adjustment = match index {
            0 | 10 => 1,
            1 => 3,
            3 => 2,
            _ => 0,
        };
        hval += asso_values[str[index] as usize + adjustment] as u32;
    }
    hval
}

// cpp: css_value_keywords.cc:4899-4910,7450-7468
fn findValueImpl(str: &[u8]) -> Option<&'static Value> {
    let len = str.len();
    if (1..=42).contains(&len) {
        let key = value_hash_function(str) as usize;
        if key <= 10935 {
            let index = lookup[key];
            if index >= 0 {
                let value = &value_word_list[index as usize];
                let s = &CSSValueStringPool[value.name_offset as usize..];
                // Safe bounds replace pointer access. Non-keyword byte 0 gives
                // a hash greater than MAX_HASH_VALUE, so strncmp's early NUL
                // termination cannot produce a successful lookup here.
                if str[0] == s[0] && s.get(len) == Some(&0) && str[1..] == s[1..len] {
                    return Some(value);
                }
            }
        }
    }
    None
}

// cpp: css_value_keywords.cc:7471-7473
// The source pointer/length pair is represented by a byte slice; callers can
// pass a subslice when looking up a prefix of a larger input buffer.
pub fn FindValue(str: &[u8]) -> Option<&'static Value> {
    findValueImpl(str)
}

// cpp: css_value_keywords.h:1195; css_value_keywords.cc:7475-7483
pub fn GetCSSValueName(id: CSSValueID) -> &'static str {
    debug_assert!(id != CSSValueID::kInvalid);
    debug_assert!((id as i32) < kNumCSSValueKeywords);
    let raw_id = id as usize;
    let start = kValueListStringOffsets[raw_id - 1] as usize;
    let end = kValueListStringOffsets[raw_id] as usize - 1;
    std::str::from_utf8(&kValueListStringPool[start..end])
        .expect("generated CSS value keyword names are ASCII")
}

// cpp: css_value_keywords.h:1197-1200
// Rust's orphan rules prevent adding From<&[u8]> to foundation string types,
// so this local trait expresses the source template's constructor constraint.
pub trait CSSValueNameString: Sized {
    fn FromCSSValueName(bytes: &'static [u8]) -> Self;
}

impl CSSValueNameString for Vec<u8> {
    fn FromCSSValueName(bytes: &'static [u8]) -> Self {
        bytes.to_vec()
    }
}
impl CSSValueNameString for String {
    fn FromCSSValueName(bytes: &'static [u8]) -> Self {
        String::from_latin1(bytes)
    }
}
impl CSSValueNameString for AtomicString {
    fn FromCSSValueName(bytes: &'static [u8]) -> Self {
        AtomicString::from_latin1(bytes)
    }
}
impl CSSValueNameString for StringView {
    fn FromCSSValueName(bytes: &'static [u8]) -> Self {
        StringView::from(&String::from_latin1(bytes))
    }
}

pub fn GetCSSValueNameAs<StringType: CSSValueNameString>(value_id: CSSValueID) -> StringType {
    StringType::FromCSSValueName(GetCSSValueName(value_id).as_bytes())
}

// cpp: css_value_keywords.h:1202; css_value_keywords.cc:7485-7521
pub fn IsValueAllowedInMode(id: CSSValueID, mode: CSSParserMode) -> bool {
    match id {
        CSSValueID::kInternalActiveListBoxSelection
        | CSSValueID::kInternalActiveListBoxSelectionText
        | CSSValueID::kInternalInactiveListBoxSelection
        | CSSValueID::kInternalInactiveListBoxSelectionText
        | CSSValueID::kInternalQuirkInherit
        | CSSValueID::kInternalSpellingErrorColor
        | CSSValueID::kInternalGrammarErrorColor
        | CSSValueID::kInternalSearchColor
        | CSSValueID::kInternalSearchTextColor
        | CSSValueID::kInternalCurrentSearchColor
        | CSSValueID::kInternalCurrentSearchTextColor
        | CSSValueID::kInternalCenter
        | CSSValueID::kInternalMediaControl
        | CSSValueID::kInternalAutoBase
        | CSSValueID::kInternalPartialInterestContent
        | CSSValueID::kInternalVariableValue
        | CSSValueID::kInternalSimpChineseInformal
        | CSSValueID::kInternalSimpChineseFormal
        | CSSValueID::kInternalTradChineseInformal
        | CSSValueID::kInternalTradChineseFormal
        | CSSValueID::kInternalKoreanHangulFormal
        | CSSValueID::kInternalKoreanHanjaInformal
        | CSSValueID::kInternalKoreanHanjaFormal
        | CSSValueID::kInternalHebrew
        | CSSValueID::kInternalLowerArmenian
        | CSSValueID::kInternalUpperArmenian
        | CSSValueID::kInternalEthiopicNumeric
        | CSSValueID::kInternalTextareaAuto => IsUASheetBehavior(mode),
        CSSValueID::kWebkitFocusRingColor => IsUASheetBehavior(mode) || IsQuirksModeBehavior(mode),
        _ => true,
    }
}

