    #[test]
    fn all_generated_names_round_trip_through_the_original_gperf_tables() {
        assert_eq!(kValueListStringPool.len(), 12233);
        assert_eq!(CSSValueStringPool.len(), 12232);
        let mut seen = std::collections::HashSet::new();
        for (index, id) in ALL_IDS.into_iter().enumerate() {
            assert_eq!(id as usize, index + 1);
            let name = GetCSSValueName(id);
            assert!(seen.insert(name));
            let lookup_name = name.to_ascii_lowercase();
            let value = FindValue(lookup_name.as_bytes()).unwrap();
            assert_eq!(value.id, id as i32);
            let offset = value.name_offset as usize;
            assert_eq!(
                &CSSValueStringPool[offset..offset + name.len()],
                lookup_name.as_bytes()
            );
            if lookup_name != name {
                assert!(FindValue(name.as_bytes()).is_none());
            }
        }
        assert_eq!(seen.len(), 1164);
        assert_eq!(
            seen.iter().map(|name| name.len()).max(),
            Some(kMaxCSSValueKeywordLength)
        );
        assert_eq!(
            GetCSSValueNameAs::<Vec<u8>>(CSSValueID::kInherit),
            b"inherit"
        );
        assert_eq!(
            GetCSSValueNameAs::<String>(CSSValueID::kColorMix).Utf8(),
            "color-mix"
        );
        assert_eq!(
            GetCSSValueNameAs::<AtomicString>(CSSValueID::kColorMix).Utf8(),
            "color-mix"
        );
        assert_eq!(
            GetCSSValueNameAs::<StringView>(CSSValueID::kColorMix)
                .ToString()
                .Utf8(),
            "color-mix"
        );
    }

    #[test]
    fn lookup_rejects_non_keywords_and_preserves_case_and_length() {
        for input in [
            b"".as_slice(),
            b"INHERIT",
            b"inherit ",
            b" inher it",
            b"not-a-css-keyword",
            b"inherit\0",
            b"\0",
            &[255; 42],
            &[b'a'; 43],
        ] {
            assert!(
                FindValue(input).is_none(),
                "unexpected keyword for {input:?}"
            );
        }
        assert_eq!(
            FindValue(&b"inherit suffix"[..7]).unwrap().id,
            CSSValueID::kInherit as i32
        );
        // Mutate every single byte of every valid name to test hash collisions
        // and exact comparison; an accidental valid different name is allowed.
        for id in ALL_IDS {
            let name = GetCSSValueName(id);
            for index in 0..name.len() {
                let mut altered = name.as_bytes().to_vec();
                altered[index] ^= 0x80;
                assert!(FindValue(&altered).is_none());
            }
        }
    }

    #[test]
    fn all_internal_keywords_obey_the_generated_mode_switch() {
        for id in ALL_IDS {
            let name = GetCSSValueName(id);
            assert!(IsValueAllowedInMode(id, CSSParserMode::kUASheetMode));
            if name.starts_with("-internal-") {
                assert!(!IsValueAllowedInMode(id, CSSParserMode::kHTMLStandardMode));
                assert!(!IsValueAllowedInMode(id, CSSParserMode::kHTMLQuirksMode));
            } else if id == CSSValueID::kWebkitFocusRingColor {
                assert!(!IsValueAllowedInMode(id, CSSParserMode::kHTMLStandardMode));
                assert!(IsValueAllowedInMode(id, CSSParserMode::kHTMLQuirksMode));
            } else {
                assert!(IsValueAllowedInMode(id, CSSParserMode::kHTMLStandardMode));
                assert!(IsValueAllowedInMode(id, CSSParserMode::kHTMLQuirksMode));
            }
        }
        assert!(IsValueAllowedInMode(
            CSSValueID::kInvalid,
            CSSParserMode::kHTMLStandardMode
        ));
    }
